//! Product entrypoints use the same explicit f32 projection as packed input.
//! Packed expected values are fixed IEEE bit patterns, not generated by the
//! rounded projector. Native calls, transactions and authorized sessions run
//! against real Chronicle/Strata-backed in-memory databases.

use asupersync::lab::run_async_under_lab;
use asupersync::security::key::AuthKey;
use fgdb::{Database, DatabaseKeys, MemVfs, QueryResult, QueryValue, WriteBatch};
use fgdb_beacon::read::{Projection, ReadOptions, ReadPolicy, Rows, Search, VectorEncoding};
use fgdb_beacon::{DistanceMetric, HnswConfig, IndexConfig, VectorSearch};
use fgdb_delta_types::{LabelId, PropertyKeyId, RelationId, SchemaEpoch};
use fgdb_gql::algebra::GraphValue;
use fgdb_gql::{GqlParameters, GqlQueryPolicy, GraphSymbol, GraphSymbolKind};
use fgdb_types::{
    CanonicalDecimal, CanonicalF64, CanonicalScalar, CommitCx, DatabaseSecurityNamespaceId,
    PurposeContexts, VId,
};
use fgdb_warden::{Authority, Grant, QueryLimits, Scope};

const NS: DatabaseSecurityNamespaceId = DatabaseSecurityNamespaceId([0x69; 32]);
const DOC: LabelId = LabelId(1);
const SECRET: LabelId = LabelId(2);
const X: PropertyKeyId = PropertyKeyId(1);
const EMB: PropertyKeyId = PropertyKeyId(2);
const REL: RelationId = RelationId(1);

fn symbols(kind: GraphSymbolKind, name: &str) -> Option<GraphSymbol> {
    match (kind, name) {
        (GraphSymbolKind::Property, "x") => Some(GraphSymbol::Property(X)),
        (GraphSymbolKind::Property, "embedding") => Some(GraphSymbol::Property(EMB)),
        (GraphSymbolKind::Label, "Doc") => Some(GraphSymbol::Label(DOC)),
        _ => None,
    }
}

fn host() -> GqlQueryPolicy {
    GqlQueryPolicy::new(1000, 100, 10_000_000, 100_000)
}

fn float(value: f64) -> CanonicalScalar {
    CanonicalScalar::Float(CanonicalF64::new(value))
}

fn packed(bits: u32) -> CanonicalScalar {
    CanonicalScalar::bytes(f32::from_bits(bits).to_le_bytes().to_vec()).unwrap()
}

async fn database(cx: &CommitCx, hidden: bool) -> Database<MemVfs> {
    let mut db = Database::open_memory(cx, DatabaseKeys::new([0x68; 32], NS, [0x6a; 32]))
        .await
        .unwrap();
    let mut batch = WriteBatch::new(REL);
    // 0.1, a decimal just above 1 + 2^-24, and an integer midpoint.
    for (id, value, bits) in [
        (1, float(0.1), 0x3dcc_cccd),
        (
            2,
            CanonicalScalar::Decimal(
                CanonicalDecimal::from_coefficient(1_000_000_059_604_644_776).unwrap(),
            ),
            0x3f80_0001,
        ),
        (3, CanonicalScalar::Int(16_777_217), 0x4b80_0000),
    ] {
        batch.create_vertex(VId(id), vec![DOC], vec![(X, value), (EMB, packed(bits))]);
    }
    if hidden {
        // This overflows f32; an authorization-before-projection failure is
        // observable as a refusal, even though no hidden result could be sent.
        batch.create_vertex(VId(90), vec![SECRET], vec![(X, float(f64::MAX))]);
    }
    db.write(cx, batch).await.unwrap();
    db
}

fn call(arguments: &str) -> String {
    format!(
        "CALL hybrid.search(vector => [0.0], {arguments}, k => 3) \
         YIELD node, vector_distance RETURN node, vector_distance \
         ORDER BY vector_distance, node"
    )
}

fn rounded_call() -> String {
    call("vector_properties => ['x'], vector_encoding => 'coordinates-rounded'")
}

fn packed_call() -> String {
    call("vector_property => 'embedding'")
}

fn expected_distances(result: &QueryResult) -> Vec<(VId, f64)> {
    let QueryResult::Rows { rows, .. } = result else {
        panic!("expected read rows");
    };
    rows.iter()
        .map(|row| match row.as_slice() {
            [
                QueryValue::Value(GraphValue::Vertex(id)),
                QueryValue::Value(GraphValue::Scalar(CanonicalScalar::Float(distance))),
            ] => (*id, distance.get()),
            _ => panic!("unexpected result shape: {row:?}"),
        })
        .collect()
}

fn options(encoding: VectorEncoding) -> ReadOptions<PropertyKeyId, LabelId> {
    ReadOptions {
        as_of: None,
        vertex_label: Some(DOC),
        projection: Projection {
            text: None,
            vector: vec![if encoding == VectorEncoding::PackedF32Le {
                EMB
            } else {
                X
            }],
            encoding,
        },
        index: IndexConfig {
            text: None,
            vector: Some(HnswConfig::new(1, DistanceMetric::SquaredEuclidean).exact_only()),
            ..IndexConfig::default()
        },
        policy: ReadPolicy::default(),
    }
}

fn search() -> Search<'static> {
    Search::Vector {
        query: &[0.0],
        k: 3,
        mode: VectorSearch::Exact,
    }
}

#[test]
fn native_and_staged_calls_match_fixed_packed_bits_without_mutating_storage() {
    let ((), report) = run_async_under_lab(0xbeac_7101, |root| async move {
        let c = PurposeContexts::narrow_runtime_root(&root);
        let mut db = database(&c.commit(), false).await;
        let before = (db.frontier().unwrap(), db.vertices().unwrap());
        let params = GqlParameters::new();
        let packed_result = db
            .query(&c.query(), &packed_call(), &params, symbols, host())
            .unwrap();
        let rounded = db
            .query(&c.query(), &rounded_call(), &params, symbols, host())
            .unwrap();
        assert_eq!(rounded, packed_result);
        let expected: Vec<_> = [0x3dcc_cccd, 0x3f80_0001, 0x4b80_0000]
            .into_iter()
            .enumerate()
            .map(|(i, bits)| {
                let value = f64::from(f32::from_bits(bits));
                (VId(i as u128 + 1), value * value)
            })
            .collect();
        assert_eq!(expected_distances(&rounded), expected);
        for mode in ["", ", vector_encoding => 'coordinates'"] {
            let exact = call(&format!("vector_properties => ['x']{mode}"));
            assert!(
                db.query(&c.query(), &exact, &params, symbols, host())
                    .is_err()
            );
        }
        // The encoding is an ordinary typed operand; no source-text rewrite.
        let parameterized = call("vector_properties => ['x'], vector_encoding => $encoding");
        let args = GqlParameters::new()
            .with_text("encoding", "coordinates-rounded")
            .unwrap();
        assert_eq!(
            db.query(&c.query(), &parameterized, &args, symbols, host())
                .unwrap(),
            rounded
        );
        let mut txn = db.begin(&c.txn()).unwrap();
        let mut update = WriteBatch::new(REL);
        update.set_vertex_property(VId(1), X, Some(float(0.2)));
        update.set_vertex_property(VId(1), EMB, Some(packed(0x3e4c_cccd)));
        txn.write_ordered(&mut db, vec![update]).unwrap();
        let staged = txn
            .query(&db, &c.query(), &rounded_call(), &params, symbols, host())
            .unwrap();
        assert_eq!(
            staged,
            txn.query(&db, &c.query(), &packed_call(), &params, symbols, host())
                .unwrap()
        );
        assert_ne!(staged, rounded);
        txn.abort();
        assert_eq!((db.frontier().unwrap(), db.vertices().unwrap()), before);
    });
    assert!(report.lab_test_passed(), "{report:?}");
}

#[test]
fn incompatible_and_unknown_encoding_declarations_refuse_without_effects() {
    let ((), report) = run_async_under_lab(0xbeac_7102, |root| async move {
        let c = PurposeContexts::narrow_runtime_root(&root);
        let db = database(&c.commit(), false).await;
        let before = (db.frontier().unwrap(), db.vertices().unwrap());
        for arguments in [
            "vector_property => 'embedding', vector_encoding => 'coordinates-rounded'",
            "vector_property => 'embedding', vector_encoding => 'coordinates'",
            "vector_properties => ['x'], vector_encoding => 'packed'",
            "vector_properties => ['x'], vector_encoding => 'auto'",
            "vector_properties => ['x'], vector_encoding => 1",
            "vector_properties => [], vector_encoding => 'coordinates-rounded'",
        ] {
            let error = db.query(
                &c.query(),
                &call(arguments),
                &GqlParameters::new(),
                symbols,
                host(),
            );
            assert!(error.is_err(), "{arguments}");
        }
        let without_vector = "CALL hybrid.search(seeds => [1], max_hops => 0, \
            include_seeds => true, vector_encoding => 'coordinates-rounded', k => 1) \
            YIELD node RETURN node";
        assert!(
            db.query(
                &c.query(),
                without_vector,
                &GqlParameters::new(),
                symbols,
                host()
            )
            .is_err()
        );
        let explicit_packed = call("vector_property => 'embedding', vector_encoding => 'packed'");
        assert_eq!(
            db.query(
                &c.query(),
                &explicit_packed,
                &GqlParameters::new(),
                symbols,
                host()
            )
            .unwrap(),
            db.query(
                &c.query(),
                &packed_call(),
                &GqlParameters::new(),
                symbols,
                host()
            )
            .unwrap(),
        );
        assert_eq!((db.frontier().unwrap(), db.vertices().unwrap()), before);
    });
    assert!(report.lab_test_passed(), "{report:?}");
}

#[test]
fn authorization_masks_invalid_coordinates_before_rounding_and_reuse() {
    let ((), report) = run_async_under_lab(0xbeac_7103, |root| async move {
        let c = PurposeContexts::narrow_runtime_root(&root);
        let db = database(&c.commit(), true).await;
        let clean = database(&c.commit(), false).await;
        let authority =
            Authority::new(AuthKey::from_seed(7103), NS, "main", SchemaEpoch(0), 1).unwrap();
        let mut grant = Grant::read_only(
            "main",
            1000,
            QueryLimits {
                max_nodes: 1000,
                max_work: 10_000_000,
                max_rows: 100,
            },
        );
        grant.labels = Scope::only([DOC]);
        grant.properties = Scope::only([X, EMB]);
        let token = authority.issue_at(&grant, 100).unwrap();
        let params = GqlParameters::new();
        let expected = clean
            .query(&c.query(), &rounded_call(), &params, symbols, host())
            .unwrap();
        assert!(
            db.query(&c.query(), &rounded_call(), &params, symbols, host())
                .is_err()
        );
        let mut session = db
            .authorized_read_session(
                &c.query(),
                &authority,
                &token,
                "main",
                symbols,
                host(),
                || 100,
            )
            .unwrap();
        assert_eq!(
            session.query(&c.query(), &rounded_call(), &params).unwrap(),
            expected
        );
        let definition = options(VectorEncoding::CoordinatesRoundedF32);
        let prepared = session
            .prepare_beacon_index(&c.query(), &definition)
            .unwrap();
        let want = clean
            .beacon_search(&c.query(), &definition, search())
            .unwrap();
        assert_eq!(
            session
                .search_beacon_index(&c.query(), &prepared, search(), ReadPolicy::default())
                .unwrap(),
            want
        );
        session.close();
        assert!(
            session
                .search_beacon_index(&c.query(), &prepared, search(), ReadPolicy::default())
                .is_err()
        );
        // A forbidden component is absent before any numeric type inspection.
        grant.properties = Scope::only([EMB]);
        let token = authority.issue_at(&grant, 100).unwrap();
        let mut masked = db
            .authorized_read_session(
                &c.query(),
                &authority,
                &token,
                "main",
                symbols,
                host(),
                || 100,
            )
            .unwrap();
        assert!(
            masked
                .beacon_search(&c.query(), &definition, search())
                .unwrap()
                .is_empty()
        );
        masked.close();
    });
    assert!(report.lab_test_passed(), "{report:?}");
}

#[test]
fn maintained_and_historical_indexes_keep_their_frozen_rounding_definition() {
    let ((), report) = run_async_under_lab(0xbeac_7104, |root| async move {
        let c = PurposeContexts::narrow_runtime_root(&root);
        let mut db = database(&c.commit(), false).await;
        let mut definition = options(VectorEncoding::CoordinatesRoundedF32);
        let resident = db.prepare_beacon_index(&c.query(), &definition).unwrap();
        let pin = resident.snapshot();
        let handle = db
            .register_beacon_index(&c.query(), &definition, ReadPolicy::default())
            .unwrap();
        let before = pin
            .search(&c.query(), search(), ReadPolicy::default())
            .unwrap();
        // Mutating the caller's options cannot switch a retained index to exact.
        definition.projection.encoding = VectorEncoding::Coordinates;
        assert!(db.prepare_beacon_index(&c.query(), &definition).is_err());
        let mut update = WriteBatch::new(REL);
        update.set_vertex_property(VId(1), X, Some(float(0.2)));
        update.set_vertex_property(VId(1), EMB, Some(packed(0x3e4c_cccd)));
        let through = db.write(&c.commit(), update).await.unwrap();
        let after = db
            .search_beacon_index(&c.query(), &handle, search(), ReadPolicy::default())
            .unwrap();
        assert_ne!(after, before);
        assert_eq!(
            after,
            db.beacon_search(&c.query(), &options(VectorEncoding::PackedF32Le), search())
                .unwrap()
        );
        assert_eq!(
            pin.search(&c.query(), search(), ReadPolicy::default())
                .unwrap(),
            before
        );
        assert_eq!(
            resident
                .search(&c.query(), search(), ReadPolicy::default())
                .unwrap(),
            before
        );
        let status = db.beacon_index_status(&c.query(), &handle).unwrap();
        assert_eq!(status.source_sequence, through);
        assert!(status.failure.is_none());
        // Exact mode here is search over already rounded f32 values, not over
        // the original stored decimal/f64 coordinates.
        assert!(matches!(after, Rows::Vector(ref hits) if hits.len() == 3));
    });
    assert!(report.lab_test_passed(), "{report:?}");
}
